"""Intent tests for risk.max_drawdown (RISK-05, TC-08): deepest fall with its peak and trough dates."""

from __future__ import annotations

import math
from typing import Any

import pytest
from hypothesis import given
from hypothesis import strategies as st

from risk.drawdown import Drawdown, max_drawdown
from risk.types import Returns


def _returns(payload: dict[str, Any]) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _one_ticker(values: list[float]) -> Returns:
    dates = tuple(f"2024-02-{day:02d}" for day in range(2, len(values) + 2))
    return Returns(base_date="2024-02-01", dates=dates, tickers=("X",), values={"X": tuple(values)})


def _brute_force_depth(values: tuple[float, ...]) -> float:
    """Independent oracle: wealth 1 at the base date, worst trough/peak - 1 over all pairs."""
    wealth = [1.0]
    for r in values:
        wealth.append(wealth[-1] * math.exp(r))
    worst = 0.0
    for i, peak in enumerate(wealth):
        for trough in wealth[i:]:
            worst = min(worst, trough / peak - 1.0)
    return worst


@pytest.mark.intent
def test_tc08_depth_and_dates_per_ticker(golden):
    given_input, expected = golden("risk", "TC-08")
    result = max_drawdown(_returns(given_input["returns"]))
    assert [d.ticker for d in result] == [row["ticker"] for row in expected["drawdowns"]]
    for got, want in zip(result, expected["drawdowns"], strict=True):
        assert isinstance(got, Drawdown)
        assert got.depth == pytest.approx(want["depth"], abs=expected["tol"], rel=0)
        assert got.peak_date == want["peak_date"]
        assert got.trough_date == want["trough_date"]


@pytest.mark.intent
def test_tc08_peak_on_a_later_date_is_dated_there(golden):
    given_input, expected = golden("risk", "TC-08")
    result = {d.ticker: d for d in max_drawdown(_returns(given_input["returns"]))}
    want = {row["ticker"]: row for row in expected["drawdowns"]}
    assert result["X"].peak_date == want["X"]["peak_date"]
    assert result["X"].trough_date == want["X"]["trough_date"]
    assert result["X"].peak_date != given_input["returns"]["base_date"]


@pytest.mark.intent
def test_tc08_no_fall_gives_zero_depth_at_the_base_date(golden):
    given_input, expected = golden("risk", "TC-08")
    result = {d.ticker: d for d in max_drawdown(_returns(given_input["returns"]))}
    want = {row["ticker"]: row for row in expected["drawdowns"]}
    assert result["Y"].depth == pytest.approx(want["Y"]["depth"], abs=expected["tol"], rel=0)
    assert result["Y"].peak_date == given_input["returns"]["base_date"]
    assert result["Y"].trough_date == given_input["returns"]["base_date"]


@pytest.mark.intent
def test_tc08_first_day_fall_peaks_at_the_base_date(golden):
    given_input, expected = golden("risk", "TC-08")
    result = {d.ticker: d for d in max_drawdown(_returns(given_input["returns"]))}
    want = {row["ticker"]: row for row in expected["drawdowns"]}
    assert result["Z"].peak_date == given_input["returns"]["base_date"]
    assert result["Z"].trough_date == want["Z"]["trough_date"]
    assert result["Z"].depth == pytest.approx(want["Z"]["depth"], abs=expected["tol"], rel=0)


@pytest.mark.intent
def test_tied_drawdowns_report_the_first():
    a = math.log(2.0)
    returns = _one_ticker([-a, a, -a])
    (result,) = max_drawdown(returns)
    assert result.depth == pytest.approx(-0.5, abs=1e-12, rel=0)
    assert result.peak_date == returns.base_date
    assert result.trough_date == returns.dates[0]


@pytest.mark.intent
def test_all_flat_returns_have_no_fall():
    returns = _one_ticker([0.0, 0.0, 0.0])
    (result,) = max_drawdown(returns)
    assert result.depth == 0.0
    assert result.peak_date == returns.base_date
    assert result.trough_date == returns.base_date


@pytest.mark.intent
def test_contract_sample_one_drawdown_per_ticker_in_order(contract_sample):
    payload = contract_sample("risk.Returns")
    returns = _returns(payload)
    result = max_drawdown(returns)
    assert tuple(d.ticker for d in result) == returns.tickers
    allowed = (returns.base_date, *returns.dates)
    for got in result:
        assert got.depth == pytest.approx(
            _brute_force_depth(returns.values[got.ticker]), abs=1e-12, rel=0
        )
        assert got.depth <= 0.0
        assert got.peak_date in allowed
        assert got.trough_date in allowed
        assert got.peak_date <= got.trough_date


@pytest.mark.intent
@given(
    values=st.lists(
        st.floats(min_value=-0.5, max_value=0.5, allow_nan=False, allow_infinity=False),
        min_size=1,
        max_size=30,
    )
)
def test_depth_matches_the_fall_between_its_dates(values):
    returns = _one_ticker(values)
    (result,) = max_drawdown(returns)
    assert result.depth <= 0.0
    assert result.depth == pytest.approx(_brute_force_depth(returns.values["X"]), abs=1e-9)
    all_dates = (returns.base_date, *returns.dates)
    peak_i = all_dates.index(result.peak_date)
    trough_i = all_dates.index(result.trough_date)
    assert peak_i <= trough_i
    fall = math.exp(math.fsum(values[peak_i:trough_i])) - 1.0
    assert fall == pytest.approx(result.depth, abs=1e-9)

